inline void soundBankCheck(const juce::File& fixture){using namespace juce;auto require=[](bool value,const char* why){if(!value)throw std::runtime_error(why);};auto temporary=File::getSpecialLocation(File::tempDirectory).getChildFile("zlplay-sound-check-"+Uuid().toString());temporary.createDirectory();struct Cleanup{File directory;~Cleanup(){directory.deleteRecursively();}}cleanup{temporary};require(mobile::padFileNote("Pad Cs.wav")==1&&mobile::padFileNote("Pads Bb.wav")==10&&mobile::padFileNote("Cafe.wav")==-1,"desktop pad filename rules");require(!mobile::bankFile(temporary,JSON::parse("{}"),"pads",0).existsAsFile(),"empty bank is safe at first launch");require(!mobile::bankFile(temporary,JSON::parse("{\"pads\":[]}"),"pads",12).existsAsFile(),"missing pad slot is safe");Array<File> files;for(int i=0;i<12;++i){auto file=temporary.getChildFile("Input").getChildFile("Pad "+mobile::flatKey(i)+".wav");file.getParentDirectory().createDirectory();require(fixture.copyFileTo(file),"prepare sound fixture");files.add(file);}auto root=temporary.getChildFile("OldContainer/ZLPlayMobile");root.createDirectory();auto state=mobile::importSoundBank(root,"pads",files);MemoryBlock original;fixture.loadFileAsData(original);for(int i=0;i<12;++i){MemoryBlock copy;auto file=mobile::bankFile(root,state,"pads",i);require(file.existsAsFile()&&file.loadFileAsData(copy)&&copy==original,"pad copy must preserve PCM file bytes");}auto relocated=temporary.getChildFile("NewContainer/ZLPlayMobile");relocated.getParentDirectory().createDirectory();require(root.copyDirectoryTo(relocated),"simulate iOS container move");auto movedState=mobile::soundBankState(relocated);require(mobile::bankFile(relocated,movedState,"pads",0).existsAsFile(),"relative sound paths survive container change");auto oldPad=mobile::bankFile(root,state,"pads",0);require(mobile::privateFile(relocated,oldPad.getFullPathName()).existsAsFile(),"legacy private absolute paths are rebased safely");require(mobile::privateFile(relocated,"Projects/../escape")==File(),"private path traversal rejected");auto previous=root.getChildFile("sound-bank.json").loadFileAsString();files.set(1,files[0]);bool rejected=false;try{mobile::importSoundBank(root,"pads",files);}catch(const mobile::ImportError&){rejected=true;}require(rejected&&root.getChildFile("sound-bank.json").loadFileAsString()==previous,"duplicate notes must preserve previous bank");rejected=false;try{mobile::importSoundBank(root,"pads",Array<File>{fixture});}catch(const mobile::ImportError&){rejected=true;}require(rejected,"incomplete pad bank rejected");auto tooLong=temporary.getChildFile("Click-six-seconds.wav");juce::AudioBuffer<float> silence(1,44100*6);silence.clear();juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(new juce::FileOutputStream(tooLong),44100,1,16,{},0));require(writer&&writer->writeFromAudioSampleBuffer(silence,0,silence.getNumSamples()),"long click fixture");writer.reset();bool durationRejected=false;try{mobile::importSoundBank(root,"normal",Array<File>{tooLong});}catch(const mobile::ImportError&){durationRejected=true;}require(durationRejected,"Android click duration limit is five seconds");state=mobile::importSoundBank(root,"normal",Array<File>{fixture});require(mobile::bankFile(root,state,"normal").existsAsFile(),"normal click import");require(!mobile::bankFile(root,JSON::parse("{\"normal\":\"/tmp/outside.wav\"}"),"normal").existsAsFile(),"sound path restricted to private bank");}
